// Arduino Code
// Motor TERM_A connected to Pin ~3 (PWM)
// Motor TERM_B connected to GND

int motorPin = 3;

void setup() {
  pinMode(motorPin, OUTPUT);
}

void loop() {
  // Ramp up
  analogWrite(motorPin, 220);
  delay(2000);

  // Slow
  analogWrite(motorPin, 80);
  delay(1000);

  // Stop
  analogWrite(motorPin, 0);
  delay(1000);
}
